import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]))
trans=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
perms=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
def nominal(p):
    return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,k):
    pos={j:p.index(j)+1 for j in jobs}
    if k=='rain':
        return None if pos['C']==5 or pos['A']==1 else nominal(p)+8*(pos['E']-1)
    if k=='road':
        return None if pos['B']==1 or pos['C']==2 else nominal(p)+5*max(0,pos['D']-3)
    return None if pos['D']==5 or pos['B']==5 else nominal(p)+5*max(0,pos['E']-2)
records=[]
for p in perms:
    neighbors={p:0}
    for i,j in itertools.combinations(range(5),2):
        q=list(p); q[i],q[j]=q[j],q[i]; q=''.join(q)
        if q.index('A')<q.index('D'): neighbors[q]=1
    best={}
    for k in ['rain','road','lift']:
        opts=[(incident(q,k)+fee,q) for q,fee in neighbors.items() if incident(q,k) is not None]
        if not opts: break
        best[k]=min(opts)
    if len(best)==3:
        records.append((nominal(p)+max(v[0] for v in best.values()),p,best))
records.sort()
score,p,best=records[0]
result={'roster':p,'score':score,'repairs':{k:v[1] for k,v in best.items()},'repair_costs':{k:v[0] for k,v in best.items()},'feasible_count':len(records),'next_score':min(x[0] for x in records if x[0]>score)}
# Independent traversal: test every permitted final via Hamming distance rather than generating exchanges.
check=[]
for pub in perms:
    costs=[]
    for kind in ['rain','road','lift']:
        vals=[]
        for final in perms:
            distance=sum(a!=b for a,b in zip(pub,final))
            if distance not in (0,2): continue
            v=incident(final,kind)
            if v is not None: vals.append(v+(distance==2))
        if not vals: break
        costs.append(min(vals))
    if len(costs)==3: check.append((nominal(pub)+max(costs),pub))
assert sorted(check)==sorted((s,p) for s,p,b in records)
assert len(perms)==60
print(json.dumps(result))
print('Verification: all 60 precedence-valid publications independently checked; chosen published nominal cost =',nominal(p))

