import itertools,json
jobs='ABCDE'; published='EABDC'
slots=[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]
trans=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
def distance(q):
    mapping=[published.index(j) for j in q]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i); i=mapping[i]
    return 5-cycles
def cost(q,d):
    ids=[jobs.index(j) for j in q]
    nominal=sum(slots[j][i] for i,j in enumerate(ids))+sum(trans[a][b] for a,b in zip(ids,ids[1:]))
    return nominal+8*q.index('E')+d+(10 if d==2 else 0)
groups={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
    q=''.join(p); d=distance(q)
    if d>2 or q.index('A')>q.index('D') or q[4]=='C' or q[0] in 'AE': continue
    groups[d].append((cost(q,d),q))
# Verify distances independently by breadth-first exchanges; intermediate states are unrestricted.
reach={published:0}; frontier=[published]
for d in (1,2):
    nxt=[]
    for q in frontier:
        for i,j in itertools.combinations(range(5),2):
            r=list(q); r[i],r[j]=r[j],r[i]; r=''.join(r)
            if r not in reach: reach[r]=d; nxt.append(r)
    frontier=nxt
for q,d in reach.items(): assert distance(q)==d
assert all((distance(''.join(p))<=2)==(''.join(p) in reach) for p in itertools.permutations(jobs))
score,roster=min(x for g in groups.values() for x in g)
result={'roster':roster,'score':score,'best_by_swaps':{str(d):min(g)[0] if g else None for d,g in groups.items()},'feasible_by_swaps':{str(d):len(g) for d,g in groups.items()}}
print(json.dumps(result))
print('Best candidates:',{d:sorted(g)[:3] for d,g in groups.items()})

